def change_labs(platforms):
    successful_ways = 0
    flipped_labs = 0

    for i in range(1, len(platforms)):
        if platforms[i] != 0:
            if platforms[i-1] < platforms[i]:
                successful_ways += 1
            elif platforms[i-1] > platforms[i]:
                flipped_labs += 1

    if succesful_ways == 1 and not flipped_labs:
        return 0
    elif succesful_ways == 1 and flipped_labs == 1:
        return 1
    elif succesful_ways == 0 and flipped_labs >= 1:
        return flipped_labs

    return min(flipped_labs-1, 1)

