from operator import mul

# quick power for modular exponentiation
def quick_power(x, y, p):
    x %= p
    res = 1
    while y:
        if y & 1:
            res = mul(res, x, p)
        y >>= 1
        x = mul(x, x, p)
    return res

# computes the mod inverse of 'b' modulo 'p'
def mod_inv(b, p):
    return quick_power(order(p, b), order(p, p-2), p)

# computes z mod n
def mod_z(p, z, n):
    return ((z % n) + p) % n

# computes the order of an integer 'a' modulo 'p'
def order(p, a):
    # is prime
    while (quick_power(a, 2, p) != a) and (a % 2 != 0):
        a = quick_power(a, 2, p)
    r = p
    # if number is not prime, preform trial division to find factors of the prime
    if (a % 2 == 0):
        while (a % 2 == 0):
            a //= 2
    assert (a % (p-1) == 1)
    factor = order(p-1, a)
    while (r % factor == 0):
        r //= factor
    assert (r % (p-1) == 1)
    return r

# reduce by addition from right to left
