import heapq

def find_largest_window_with_size(n, k):
    # Build the graph with the platforms and edges
    graph = defaultdict(list)
    for i in range(1, n+1):
        graph[1].append(i*i-n)
        graph[i*i-n].append(1)
        for i in range(k):
            graph[i*i-n].append((i+i*n)**2-n*i)
            graph[(i+i*n)**2-n*i].append(i*n+i)
        graph[i*i-n].append((i*(i*n)-i*i)**2-n*i*i)
        graph[(i*(i*n)-i*i)**2-n*i*i].append(i*i-1*i)

    nodes_with_dummies = defaultdict(set)
    dummy_nodes = set()
    for step, dependency in reversed(list(enumerate(graph))):
        for i in dependency:
            nodes_with_dummies[i].add((step+1, i))
    node_queue = []
    for step, dependency in sorted(nodes_with_dummies.items()):
        for i in dependency:
            heapq.heappush(node_queue, (1, i))
    while node_queue:
        step, node = heapq.heappop(node_queue)
        if step > k:
            break
        if nodes_with_dummies.get(node, False):
            for i in nodes_with_dummies[node]:
                if i < step:
                    heapq.heappush(node_queue, i, node_queue)
            if len(node_queue) >= 2:
                node_queue[0] = (node_queue[0][1] + 1, node)
    largest_flows = [c[0] for c in heapq.merge(*node_queue)]
    return len(node_queue)-1, largest_flows[-1]

