from math import gcd

def lcm(a, b):
    return a * b // gcd(a, b)

# Helper function to get the discrete logarithm of an element with respect to a cyclic group
def discrete_log(x, base, order):
    for y in range(1, order):
        if base ** y % x == 1:
            return y
    return None

# Initialize the Euler's Totient Function for a list of numbers
def euler_totient(numbers):
    results = [1] * len(numbers)
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            if gcd(numbers[i], numbers[j]) == 1:
                results[i] = lcm(results[i], (numbers[j] - 1) * (numbers[j] - 2)) // (numbers[j] - 2)
    return results

# Extract a prefix of the string to calculate the minimal name of a meeting room
def get_prefix(s):
    match = 1
    current_char = s[0]
    prefix_length = 1
    for i in range(1, len(s)):
        if s[i] >= current_char:
            current_char = s[i]
            prefix_length += 1
        else:
            break
    return prefix_length

def calculate_kth_label(n, m, k, s):
    euler_numbers = euler_totient([ord(c) - ord('a') + 1 for c in s])

    z = k
    h = k

    # Calculate the z-value for each string length
    z_values = euler_numbers[:]
    for i in range(1, n + 1):
        z_values[i] = stdModIfInf(z_values[i] + z_values[i - 1], euler_numbers[i - 1])

    # Calculate the h-value
    h_values = euler_numbers[:]
    for i in range(1, n + 1):
        h_values[i] = stdModIfInf(h_values[i - 1] - h_values[i - euler_numbers[i - 1]], euler_numbers[i - 1])

    for i in range(1, n + 1):
        z, h = z, h

    for i in range(1, n + 1):
        z, h = supportModIfInf(z, h_values[i], euler_numbers[i])

    for i in range(n, 1, -1):
        z, h = supportModIfInf(z, h_values[i - 1], euler_numbers[i - 1])

    z -= 1

    # Calculate the integer value for which k = z^m * h
    a = pow(z, m)
    g = pow(h, euler_numbers[n] - euler_numbers[n - m])
    k = multiply(a, g, euler_numbers[n])

    # Update z and h
    z = multiply(z, euler_numbers[n] - euler_numbers[n - m], euler_numbers[n])

    index = -1

    for i in range(n, 1, -1):
        a = multiply(z, mapper(i - 1), euler_numbers[i - 1])
        g = multiply(h_values[i - 1], mapper(i - 1), euler_numbers[i - 1])

        if multiplicative_order_mod_inf(divide(a, g, euler_numbers[i - 1]) < euler_numbers[i]):
            index = i
            break

    if index < 0:
        return s
    else:
        return s[index:n:index]

def mapper(x):
    return euler_numbers[x]

def stdModIfInf(x, divisor):
    if x < 0:
        return x + divisor
    else:
        return x

def supportModIfInf(x, divisor):
    return x - divisor * ((x // divisor) + 1)
    
def multiply(x, y, divisor):
    return (x * y) // divisor

def divide(x, y, divisor):
    return x * multiplicative_order_mod_inf(divisor // y)

def multiplicative_order_mod_inf(a):
    multiplied = 1
    
    while 1:
        multiplied = multiply(multiplied, a)
