from collections import defaultdict

def flip(corners):
    return [(corners[j][2], corners[j][3], corners[j][0], corners[j][1]) for j in range(4)]

def rotate_z():
    return [(corners[i][2], corners[i][0], corners[i][3], corners[i][1]) for i in range(4)]

def rotate_y():
    return [(corners[i][0], corners[i][3], corners[i][2], corners[i][1]) for i in range(4)]

def rotate_x():
    return [(corners[i][3], corners[i][2], corners[i][0], corners[i][1]) for i in range(4)]

def build_cube(directions):
    tiles = defaultdict(list)

    for i in range(1, N+1):
        for d in directions[i-1]:
            tiles[corners[d]].append(i)

    cubes = set()

    def dfs(queue):
        # Construct a cube using the corners of the tiles in the queue
        C = sorted([(corners[tile-1][0], corners[tile-1][1], corners[tile-1][2], corners[tile-1][3]) for tile in queue], reverse=True)
        cubes.add(tuple(C))

        # Unmark the spot where the tile was placed
        for tile in queue:
            corners[tile-1] = (None, None, None, None) # Markered spot

        # Put the tile back at the origin of the axes
        for d in range(4): 
            if queue: corners[tiles[queue[0]][-1]][d] = queue.pop()

    # Six cycles of rotations
    for _ in range(6):
        queue = []
        for d in directions[0]:
            for tile in tiles[d]: # Pick every tile
                queue.append(tile)
        dfs(queue)
        directions[0] = flip(directions[0]) # Rotate x-axis

        for r in range(12):
            # Rotate z-axis
            queue = rotate_z()

            for d in directions[r]:
                for tile in tiles[d]:
                    queue.append(tile)

            dfs(queue)
            directions[r] = rotate_y() # Rotate y-axis

            # Rotate y-axis
            queue = rotate_y()

            for d in directions[-r]:
                for tile in tiles[d]:
                    queue.append(tile)

            dfs(queue)
            directions[-r] = rotate_z()

            # Rotate z-axis
            queue = []

            # Rotate x-axis
            for d in directions[r]:
                for tile in tiles[d]:
                    queue.append(tile)

            dfs(queue)
            directions[r] = flip(directions[r])

    # Remove the duplicate cubes
    return len(cubes)

def solve():
    N = int(input().strip())
