def add_or_modify(graph, src, dst, weight, mod_type):
    edge = src + '-' + dst
    if mod_type == 'in':
        mod_type = '<'
    elif mod_type == 'out':
        mod_type = '>'
    if edge not in graph[mod_type]:
        graph[mod_type][edge] = defaultdict(int)
    graph[mod_type][edge][dst] += 1
    if dst in graph['other'] and mod_type in ('in', 'out'):
        graph['other'][dst][src] += 1
    if mod_type in ('in', 'out'):
        weight = graph[mod_type][edge]['weight'] = weight

def dijkstra(graph, src, dest):
