from collections import deque

def color_breadboard(last, row_col, modifications):
    color = deque(last)
    max_capacity = 0

    for modifier in modifications:
        if modifier[0] == 'U':
            color = deque(map(lambda x: 1 if x == last[0] else -1, color))
        elif modifier[0] == 'D':
            color = deque(map(lambda x: 1 if x == last[1] else -1, color))
        else:
            s = modifier[0]
            l = modifier[1] - 1
            r = modifier[2] - 1
            if s == 'L':
                if l <= row_col[2]:
                    color[row_col[1]] = -color[row_col[1]]
            elif s == 'R':
                if r <= row_col[2]:
                    color[row_col[3]] = -color[row_col[3]]

            if s == 'U':
                color[0] = -color[0]
            elif s == 'D':
                color[-1] = -color[-1]

        for i in range(1, len(color)):
            if color[i-1] + color[i] != 0:
