from bisect import bisect_left, bisect_right

def find_weight(edge, edges, vertex_lookup):
    left = vertex_lookup[edge[0]]
    right = vertex_lookup[edge[1]]
    min_weight = None
    max_weight = None
    for v, w in edges[left:right+1]:
        if v == edge[0] or v == edge[1]:
            continue
        if min_weight is None or w < min_weight:
            min_weight = w
        if max_weight is None or w > max_weight:
            max_weight = w
    if min_weight is None:
        return 0
    if not (edge[0] in edges and edge[1] in edges):
        return -1
    edge_weight_left = edges[edge[0]][bisect_left(edges[edge[0]], edge[0])]
    edge_weight_right = edges[edge[1]][bisect_right(edges[edge[1]], edge[1])]
    edge_edge_left = min(min_weight, bisect_right(edges[edge[0]], edge[1]))
    edge_edge_right = min(max_weight, bisect_left(edges[edge[1]], edge[0]))
    return max(0, edge_edge_left - edge_weight_left + edge_weight_right - edge_edge_right)
