def is_bipartite(graph, start):
    color = {0: 'red', 1: 'green'}
    visited = set()

    def dfs(vertex):
        if vertex in visited:
            return
        visited.add(vertex)
        for neighbor in graph[vertex]:
            if color[neighbor % 2] == 'green' and color[vertex % 2] == 'green':
                return False
            if color[neighbor % 2] == 'red' and color[vertex % 2] == 'red':
                return False
            if not dfs(neighbor):
                return False
        return True

    return dfs(start)

